    /// - `shape`: A vector of two unsigned bytes representing the desired shape [R, C].
    ///
    /// # Returns
    /// A matrix of dimensions R x C, filled according to the broadcasting rules.
    #[verifier::requires(a.len() > 0)]
    #[verifier::requires(shape.len() == 2)]
    #[verifier::requires(shape[0] > 0)]
